const source = $('Execute Workflow Trigger').item.json || {};
const payload = source.payload || {};
const message = source.message || payload.message || payload.body?.message || {};
const chatId = source.chatId || message.chat?.id || payload.chatId || '';
const raw = String(source.rawText || message.text || payload.text || '').trim();
const query = raw
  .replace(/^(doc mail|đọc mail|doc email|đọc email|noi dung mail|nội dung mail|noi dung email|nội dung email|read mail|read email|open mail|open email)\s*/i, '')
  .replace(/\s+/g, ' ')
  .trim();
const hasQuery = Boolean(query);
const guidance = '📧 <b>Đọc email</b>\n\nBạn hãy nhập theo mẫu:\n- đọc mail từ Google\n- nội dung mail về đơn hàng\n- read mail from boss';
return [{ json: { ...source, payload, message, chatId, query, hasQuery, response: hasQuery ? '' : guidance } }];

const source = $('Chuan Bi Doc Email').item.json;

const escapeHtml = (value = '') => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/\"/g, '&quot;');

const pickFirst = (...values) => {
  for (const value of values) {
    if (value === undefined || value === null) continue;
    if (typeof value === 'string' && value.trim()) return value.trim();
    if (typeof value === 'number' && Number.isFinite(value)) return String(value);
  }
  return '';
};

const formatDate = (value) => {
  if (value === undefined || value === null || value === '') return '';
  const normalized = /^\d+$/.test(String(value)) ? Number(value) : value;
  const date = new Date(normalized);
  return Number.isNaN(date.getTime()) ? '' : date.toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' });
};

const buildMailLink = (email) => {
  const threadId = pickFirst(email.threadId);
  const messageId = pickFirst(email.id);
  if (threadId) return `https://mail.google.com/mail/u/0/#inbox/${threadId}`;
  if (messageId) return `https://mail.google.com/mail/u/0/#inbox/${messageId}`;
  return '';
};

const rows = $input.all().map((item) => item.json || {}).filter((e) => e && Object.keys(e).length > 0 && (e.id || e.subject || e.Subject || e.from || e.From || e.snippet));
if (rows.length === 0) {
  return [{ json: { chatId: source.chatId, text: '⚠️ Không tìm thấy email phù hợp với: ' + source.query } }];
}

const email = rows[0];
const from = pickFirst(email.from?.value?.[0]?.name, email.from?.value?.[0]?.address, email.From, email.from, email.payload?.headers?.find((h) => h.name === 'From')?.value) || 'Không rõ';
const to = pickFirst(email.to?.value?.[0]?.address, email.To, email.to, email.payload?.headers?.find((h) => h.name === 'To')?.value);
const subject = pickFirst(email.subject, email.Subject, email.payload?.headers?.find((h) => h.name === 'Subject')?.value) || 'Không có tiêu đề';
const date = formatDate(pickFirst(email.date, email.Date, email.internalDate));
const link = buildMailLink(email);

let body = pickFirst(email.textPlain, email.text, email.snippet) || '(Không có nội dung văn bản để hiển thị)';
if (body.length > 1500) body = body.substring(0, 1500) + '\n\n... (nội dung đã được cắt bớt)';

let text = '📧 <b>Chi tiết email</b>\n\n';
text += `📝 <b>${escapeHtml(subject)}</b>\n`;
text += `👤 Từ: ${escapeHtml(from)}\n`;
if (to) text += `📨 Đến: ${escapeHtml(to)}\n`;
if (date) text += `🕒 ${escapeHtml(date)}\n`;
if (link) text += `🔗 <a href="${escapeHtml(link)}">Link</a>\n`;
text += `\n${escapeHtml(body)}`;

return [{ json: { chatId: source.chatId, text: text.trim() } }];
